INSERT INTO ist (id, gravite, incidence, long_description, nom, short_description, type_ist) VALUES
(1, 5, 5100, 'Le VIH est un retrovirus qui attaque le systeme immunitaire, surtout les lymphocytes T CD4. Sans traitement, l''infection peut evoluer vers le sida. Le traitement antiretroviral ne guerit pas mais controle durablement le virus, protege la sante et reduit fortement le risque de transmission lorsque la charge virale reste indetectable.', 'vih', 'Evolue vers sida', 'viral'),
(2, 3, 61100, 'La chlamydiose est une IST bacterienne due a Chlamydia trachomatis. Elle touche le col, l''uretre, le rectum ou la gorge. Elle est tres souvent asymptomatique, ce qui facilite sa transmission. Non traitee, elle peut provoquer une infection genitale haute, des douleurs pelviennes et des problemes de fertilite, surtout chez la femme.', 'chlamydiose', 'Souvent invisible', 'bacterien'),
(3, 3, 25800, 'La gonorrhee, ou infection a gonocoque, est une IST bacterienne due a Neisseria gonorrhoeae. Elle peut causer des brulures en urinant, des ecoulements genitaux, des douleurs pelviennes, une infection rectale ou de la gorge, mais peut aussi passer inapercue. Non traitee, elle peut entrainer des complications genitales et favoriser la transmission du VIH.', 'gonorrhee', 'Brulures/ecoulement', 'bacterien'),
(4, 4, 6500, 'La syphilis est une IST bacterienne due a Treponema pallidum. Elle evolue par stades. Elle debute souvent par une plaie indolore appelee chancre, puis peut provoquer des signes cutanes ou generaux. Sans traitement, elle peut atteindre le systeme nerveux, le coeur ou d''autres organes plusieurs annees apres l''infection.', 'syphilis', 'Chancre puis grave', 'bacterien'),
(5, 3, 36000, 'L''herpes genital est une infection virale chronique due aux virus herpes simplex HSV-1 ou HSV-2. Il peut provoquer des vesicules ou ulcerations douloureuses au niveau genital, anal ou perineal. Le virus reste dans l''organisme et peut se reactiver. La transmission est possible pendant les poussees et parfois en dehors des symptomes.', 'herpes genital', 'Poussees douloureus', 'viral'),
(6, 4, NULL, 'Les papillomavirus humains sont des vsirus tres frequents transmis surtout par contact sexuel peau a peau ou muqueuse a muqueuse. La plupart des infections disparaissent seules. Certains types peuvent causer des verrues genitales, d''autres des lesions precancereuses et des cancers du col de l''uterus, de l''anus, du penis ou de la gorge.', 'hpv', 'Virus tres frequent', 'viral'),
(7, 4, NULL, 'L''hepatite B est une infection virale du foie due au VHB. Elle se transmet par le sang, les rapports sexuels et de la mere a l''enfant. Elle peut etre aigue ou devenir chronique, avec risque de cirrhose et de cancer du foie. La vaccination est la prevention principale et protege aussi contre l''hepatite Delta chez les personnes non infectees par le VHB.', 'hepatite_b', 'Atteinte du foie', 'viral'),
(8, 4, NULL, 'L''hepatite C est une infection virale du foie due au VHC. La transmission est surtout sanguine, notamment par partage de materiel d''injection, mais une transmission sexuelle peut exister dans certains contextes. L''infection devient souvent chronique si elle n''est pas traitee. Les antiviraux a action directe guerissent la majorite des infections.', 'hepatite_c', 'Virus du sang', 'viral'),
(9, 2, NULL, 'La trichomonase est une IST due au parasite Trichomonas vaginalis. Elle peut provoquer des pertes vaginales, une irritation, des demangeaisons ou des brulures urinaires, mais elle est parfois asymptomatique. Chez l''homme, elle peut causer une uretrite discrete. Le traitement repose sur des medicaments de la famille des nitro-imidazoles.', 'trichomonase', 'Parasite genital', 'parasite'),
(10, 3, NULL, 'Mycoplasma genitalium est une bacterie sexuellement transmissible pouvant provoquer une uretrite, une cervicite, une infection rectale ou des douleurs pelviennes. Elle peut aussi etre peu symptomatique. Sa prise en charge doit tenir compte du risque de resistance aux macrolides et se fait selon prescription medicale.', 'mycoplasma', 'IST discrete', 'bacterien'),
(11, 3, NULL, 'La lymphogranulomatose venerienne est une IST due a certains types invasifs de Chlamydia trachomatis. Elle peut debuter par une petite lesion passee inapercue, puis provoquer des ganglions douloureux ou une rectite avec douleurs, saignements et ecoulements. Elle est traitee plus longtemps que la chlamydiose genitale commune.', 'lgv', 'Chlamydia invasive', 'bacterien'),
(12, 3, NULL, 'Le chancre mou est une IST bacterienne due a Haemophilus ducreyi. Elle provoque des ulceres genitaux douloureux et parfois des ganglions inflammatoires dans l''aine. Elle est rare en France metropolitaine et plus presente dans certaines zones tropicales. Le traitement repose sur des antibiotiques adaptes.', 'chancre_mou', 'Ulceres douloureux', 'bacterien'),
(13, 3, NULL, 'La donovanose, ou granulome inguinal, est une IST bacterienne rare due a Klebsiella granulomatis. Elle provoque des ulcerations genitales chroniques, souvent peu douloureuses mais destructrices si elles ne sont pas traitees. Elle concerne surtout certaines zones tropicales et necessite un traitement antibiotique prolonge.', 'donovanose', 'Ulceres chroniques', 'bacterien'),
(14, 2, NULL, 'La gale est une parasitose de la peau due a Sarcoptes scabiei. Elle n''est pas uniquement sexuelle, mais peut se transmettre lors de contacts corporels rapproches et prolonges, y compris sexuels. Elle provoque des demangeaisons intenses, souvent nocturnes. Le traitement doit souvent concerner les contacts proches et le linge.', 'gale', 'Prurit nocturne', 'parasite'),
(15, 1, NULL, 'Les poux pubiens, ou morpions, sont des parasites transmis le plus souvent par contact intime direct. Ils provoquent des demangeaisons du pubis et parfois de petites lesions de grattage. La prise en charge repose sur un traitement antiparasitaire, le lavage du linge et l''information des partenaires recents.', 'poux_pubiens', 'Prurit pubien', 'parasite'),
(16, 1, NULL, 'Le molluscum contagiosum est une infection virale de la peau qui peut se transmettre par contact cutane direct, y compris lors de contacts sexuels chez l''adulte. Il provoque de petites papules arrondies, parfois situees dans la region genitale. Les lesions peuvent disparaitre seules ou etre traitees localement si necessaire.', 'molluscum', 'Petites papules', 'viral');
